import{eventAliasMap}from"../config/eventAliasMap.js";export default class EventService{constructor(options={}){this._options=options;this._selector=options.selector||"#dyjsform";this._debugMode=options.debugMode||false;this._eventAliasMap=eventAliasMap}dispatchEvent(eventName,detail){if(this._eventAliasMap[eventName]){const event=this._resolveAlias(eventName);const customEvent=new CustomEvent(event,{detail:detail,bubbles:true,cancelable:true});document.dispatchEvent(customEvent);this._debugMode&&console.log("event triggered: "+this._resolveAlias(eventName))}}_resolveAlias(event){return`${this._selector}.${this._eventAliasMap[event]||event}`}}